import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.DNmTgtHf.js";const k=JSON.parse('{"title":"Static Factory Methods — Effective Java Item 1","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/creational/static_factory_methods/StaticFactoryMethods.md","filePath":"design_patterns/creational/static_factory_methods/StaticFactoryMethods.md"}'),n={name:"design_patterns/creational/static_factory_methods/StaticFactoryMethods.md"};function o(r,e,h,l,c,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="static-factory-methods-—-effective-java-item-1" tabindex="-1">Static Factory Methods — Effective Java Item 1 <a class="header-anchor" href="#static-factory-methods-—-effective-java-item-1" aria-label="Permalink to &quot;Static Factory Methods — Effective Java Item 1&quot;">​</a></h1><p>A <strong>static factory method</strong> is a static method on a class that returns an instance of <em>that same class</em>. It&#39;s an alternative path to construction, parallel to the constructor, and the most common &quot;factory-ish&quot; shape in modern Java.</p><p>This is not a GoF pattern; it&#39;s an idiom from <em>Effective Java</em> Item 1, &quot;Consider static factory methods instead of constructors.&quot; This package walks the idea with a small <code>Temperature</code> demo and grounds the five benefits with examples from this repo and the JDK.</p><h2 id="the-strict-definition-and-the-trap" tabindex="-1">The strict definition (and the trap) <a class="header-anchor" href="#the-strict-definition-and-the-trap" aria-label="Permalink to &quot;The strict definition (and the trap)&quot;">​</a></h2><p>Bloch&#39;s strict definition: a static method that returns <em>an instance of the class it&#39;s declared on</em>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Declared on</th><th>Returns</th><th>Static factory method <em>for</em>…</th></tr></thead><tbody><tr><td><code>Boolean.valueOf(true)</code></td><td><code>Boolean</code></td><td><code>Boolean</code></td><td><code>Boolean</code> ✅</td></tr><tr><td><code>List.of(1, 2, 3)</code></td><td><code>List</code></td><td><code>List</code></td><td><code>List</code> ✅</td></tr><tr><td><code>Temperature.celsius(20)</code></td><td><code>Temperature</code></td><td><code>Temperature</code></td><td><code>Temperature</code> ✅</td></tr><tr><td><code>JobOffer.builder()</code></td><td><code>JobOffer</code></td><td><code>JobOfferBuilder</code></td><td><strong>Not</strong> <code>JobOffer</code> — it&#39;s a static method on <code>JobOffer</code> that helps with construction, but the term reserves itself for the same-class case</td></tr></tbody></table><p>Most casual writing on the topic ignores this distinction. Item 1&#39;s benefits all assume the strict form.</p><h2 id="the-five-benefits-over-constructors" tabindex="-1">The five benefits over constructors <a class="header-anchor" href="#the-five-benefits-over-constructors" aria-label="Permalink to &quot;The five benefits over constructors&quot;">​</a></h2><h3 id="_1-they-have-names" tabindex="-1">1. They have names <a class="header-anchor" href="#_1-they-have-names" aria-label="Permalink to &quot;1. They have names&quot;">​</a></h3><p>Constructor overloads collapse meaning:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// What does this construct? You have to read the docs.</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BigInteger</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bitLength, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> certainty, Random rnd);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Self-documenting:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BigInteger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">probablePrime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bitLength, rnd);</span></span></code></pre></div><p>In this package, <code>Temperature</code> is the headline example: three factories that all take a single <code>double</code> — no overloaded constructor could disambiguate them.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Temperature.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celsius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 20°C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Temperature.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fahrenheit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">68</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 68°F</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Temperature.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kelvin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">293.15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 293.15K</span></span></code></pre></div><h3 id="_2-they-are-not-required-to-create-a-new-object-each-call" tabindex="-1">2. They are not required to create a new object each call <a class="header-anchor" href="#_2-they-are-not-required-to-create-a-new-object-each-call" aria-label="Permalink to &quot;2. They are not required to create a new object each call&quot;">​</a></h3><p>This is the headline benefit. Constructors must always allocate; static factories don&#39;t.</p><p>The JDK leans on this constantly:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Boolean.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valueOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// returns the singleton Boolean.TRUE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Integer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valueOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// returns a cached Integer for values in -128..127</span></span></code></pre></div><p>In <code>Temperature</code>, every factory funnels through a <code>ConcurrentHashMap</code> cache, so:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Temperature a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Temperature.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celsius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Temperature b </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Temperature.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">celsius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true — same instance</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Temperature c </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Temperature.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fahrenheit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">68</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true — 68°F is 20°C, and the cache key is Celsius</span></span></code></pre></div><p>This single benefit is what lets immutable value classes be space-efficient, and what enables the broader notion of <strong>instance-controlled classes</strong> — the class controls how many instances exist. Singleton is a special case (one instance allowed); flyweight is another (one per equivalence class).</p><h3 id="_3-they-can-return-any-subtype-of-their-declared-return-type" tabindex="-1">3. They can return any subtype of their declared return type <a class="header-anchor" href="#_3-they-can-return-any-subtype-of-their-declared-return-type" aria-label="Permalink to &quot;3. They can return any subtype of their declared return type&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> unmodifiableList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> extends T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> list) {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Returns an instance of a private inner class.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Callers see only List.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>Collections.unmodifiableList(...)</code> factory returns an instance of a private inner class; callers see only <code>List</code>. This lets the API hide implementation details and swap them later without breaking callers — <em>the public API is the return type, not the concrete class</em>. A constructor can&#39;t do this; it always returns an instance of <em>its own</em> class.</p><h3 id="_4-the-returned-class-can-vary-based-on-input" tabindex="-1">4. The returned class can vary based on input <a class="header-anchor" href="#_4-the-returned-class-can-vary-based-on-input" aria-label="Permalink to &quot;4. The returned class can vary based on input&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EnumSet.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(JACK, QUEEN, KING);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Returns either RegularEnumSet (≤64 elements, bitvector implementation) or</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// JumboEnumSet (&gt;64 elements, long-array implementation), depending on the</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// enum&#39;s size. Caller sees only EnumSet.</span></span></code></pre></div><p>Same method, different concrete type per call. The factory picks the optimal implementation for the input.</p><h3 id="_5-the-returned-class-need-not-exist-when-the-factory-is-written" tabindex="-1">5. The returned class need not exist when the factory is written <a class="header-anchor" href="#_5-the-returned-class-need-not-exist-when-the-factory-is-written" aria-label="Permalink to &quot;5. The returned class need not exist when the factory is written&quot;">​</a></h3><p>The &quot;service provider&quot; pattern. The factory looks up an implementation at runtime:</p><ul><li><code>DriverManager.getConnection(url)</code> finds whichever JDBC driver is on the classpath.</li><li><code>ServiceLoader.load(MyService.class)</code> discovers implementations via <code>META-INF/services/</code>.</li></ul><p>Useful for plugin architectures where the concrete class is loaded dynamically.</p><h2 id="the-two-limitations" tabindex="-1">The two limitations <a class="header-anchor" href="#the-two-limitations" aria-label="Permalink to &quot;The two limitations&quot;">​</a></h2><ol><li><strong>Classes with <em>only</em> static factories (no public/protected constructor) cannot be subclassed via <code>extends</code>.</strong> Subclasses need a parent constructor to call via <code>super(...)</code>. Some consider this a feature (it nudges callers toward composition, EJ Item 18); others see it as a real cost.</li><li><strong>They&#39;re harder to find in the docs.</strong> Constructors get a dedicated section in JavaDoc; static factories blend in with regular static methods. The standard mitigation is following the naming conventions below so they&#39;re recognisable on sight.</li></ol><h2 id="naming-conventions" tabindex="-1">Naming conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming conventions&quot;">​</a></h2><p>Following these makes intent obvious to readers:</p><table tabindex="0"><thead><tr><th>Convention</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>from</code></td><td>Type-conversion taking one parameter</td><td><code>Date.from(instant)</code>, <code>Temperature.fromString(&quot;20C&quot;)</code></td></tr><tr><td><code>of</code></td><td>Aggregation taking multiple parameters</td><td><code>List.of(a, b, c)</code>, <code>EnumSet.of(JACK, QUEEN)</code></td></tr><tr><td><code>valueOf</code></td><td>Verbose alternative to <code>from</code> / <code>of</code></td><td><code>BigInteger.valueOf(Long.MAX_VALUE)</code></td></tr><tr><td><code>instance</code> / <code>getInstance</code></td><td>Returns an instance described by parameters; may not be new</td><td><code>StackWalker.getInstance(opts)</code>, <code>Singleton.getInstance()</code></td></tr><tr><td><code>create</code> / <code>newInstance</code></td><td>Like <code>getInstance</code> but guarantees a <em>new</em> object</td><td><code>Array.newInstance(cls, len)</code></td></tr><tr><td><code>getXxx</code></td><td>Like <code>getInstance</code> but on a <em>different</em> class</td><td><code>Files.getFileStore(path)</code></td></tr><tr><td><code>newXxx</code></td><td>Like <code>newInstance</code> but on a different class</td><td><code>Files.newBufferedReader(path)</code></td></tr><tr><td><code>xxx</code></td><td>Concise alternative when meaning is obvious</td><td><code>Collections.list(enumeration)</code></td></tr></tbody></table><p>Once you see these conventions, you can&#39;t unsee them in the JDK.</p><h2 id="when-to-use-a-static-factory-method" tabindex="-1">When to use a static factory method <a class="header-anchor" href="#when-to-use-a-static-factory-method" aria-label="Permalink to &quot;When to use a static factory method&quot;">​</a></h2><p>Reach for one when at least one of these applies:</p><ul><li>You want a <strong>meaningful name</strong> to disambiguate construction strategies.</li><li>You want to <strong>cache instances</strong> for value classes that appear repeatedly.</li><li>You want to <strong>return a subtype</strong> the caller shouldn&#39;t depend on.</li><li>You want construction to <strong>defer to runtime</strong> (service-provider pattern).</li></ul><p>Stick with a plain constructor when none of these apply. Static factories aren&#39;t always better — they&#39;re better when one of the five benefits actively earns its keep.</p><h2 id="how-this-connects-to-other-patterns-in-this-repo" tabindex="-1">How this connects to other patterns in this repo <a class="header-anchor" href="#how-this-connects-to-other-patterns-in-this-repo" aria-label="Permalink to &quot;How this connects to other patterns in this repo&quot;">​</a></h2><p>Three connections worth keeping in your head:</p><ol><li><p><strong>Singleton&#39;s <code>getInstance()</code> is itself a static factory method.</strong> The Singleton &quot;pattern&quot; is a special case of EJ Item 1&#39;s benefit #2: the factory chooses not to create a new instance. Your four singleton variants in <code>creational/singleton/</code> are all named per the <code>getInstance</code> convention.</p></li><li><p><strong>Simple Factory&#39;s <code>EmployeeFactory.create(EmployeeType)</code> returns <code>Employee</code>, not <code>EmployeeFactory</code>.</strong> So strictly per Bloch, it&#39;s <em>not</em> a static factory method <em>for <code>EmployeeFactory</code></em>. It&#39;s a static method on <code>EmployeeFactory</code> that&#39;s a factory — different thing. Most Java tutorials are loose with this; the distinction sharpens once Item 1 clicks.</p></li><li><p><strong><code>JobOffer.builder()</code> is the same trap.</strong> Static method on <code>JobOffer</code>, but returns <code>JobOfferBuilder</code>, so not a static factory method <em>for <code>JobOffer</code></em>. A real static factory method for <code>JobOffer</code> would look like <code>JobOffer.of(salary, city)</code>.</p></li></ol><h2 id="the-demo-class" tabindex="-1">The demo class <a class="header-anchor" href="#the-demo-class" aria-label="Permalink to &quot;The demo class&quot;">​</a></h2><p><code>Temperature.java</code> shows the two most common benefits in practice:</p><ul><li><strong>Names disambiguate:</strong> <code>celsius</code>, <code>fahrenheit</code>, <code>kelvin</code> — three factories with identical signatures that overloaded constructors could not represent.</li><li><strong>Instance control:</strong> all factories funnel through a <code>ConcurrentHashMap</code> cache; equivalent inputs return the same instance regardless of which factory was called.</li></ul><p>The runner (<code>TemperatureRun.java</code>) walks five scenarios:</p><ol><li>Three named factories all encoding 20°C from different units.</li><li>The <code>from</code> convention via <code>fromString(&quot;100C&quot;)</code>.</li><li><code>==</code> checks proving the cache: <code>celsius(20) == fahrenheit(68)</code> is <code>true</code>.</li><li><code>absoluteZero()</code> returns the same singleton on every call.</li><li>Validation: invalid Kelvin and unknown units throw.</li></ol><p>Run it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec:java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dexec.mainClass=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org.example.design_patterns.creational.static_factory_methods.TemperatureRun&quot;</span></span></code></pre></div><h2 id="caveat-about-the-demo-s-caching" tabindex="-1">Caveat about the demo&#39;s caching <a class="header-anchor" href="#caveat-about-the-demo-s-caching" aria-label="Permalink to &quot;Caveat about the demo&#39;s caching&quot;">​</a></h2><p><code>Temperature</code> uses an unbounded <code>ConcurrentHashMap</code> for the cache. That&#39;s fine for a teaching demo but a leak risk in production code — the cache grows forever. Real-world variants either cap the cache (LRU / weak references) or apply caching only to a known-finite domain (<code>Boolean.valueOf</code>&#39;s two values, <code>Integer.valueOf</code>&#39;s <code>-128..127</code> range). Worth knowing the pattern; worth not copying the unbounded form.</p><h2 id="when-constructors-are-still-right" tabindex="-1">When constructors are still right <a class="header-anchor" href="#when-constructors-are-still-right" aria-label="Permalink to &quot;When constructors are still right&quot;">​</a></h2><ul><li>One construction strategy, no naming issue, no caching, no subtypes — just write <code>new</code>.</li><li>You want callers to subclass via inheritance — static factories alone don&#39;t enable this.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><code>creational/CreationalPatternsRoadmap.md</code> — this is &quot;Side Quest A&quot; between Builder and Abstract Factory.</li><li><code>creational/singleton/Singleton.md</code> — <code>getInstance()</code> is the canonical static factory method; the Singleton pattern is a special case of Item 1.</li><li><code>creational/factory/Factory.md</code> — Simple Factory&#39;s <code>create(...)</code> is a static method that <em>is</em> a factory but is not strictly an Item-1 static factory method; the doc clarifies the terminology.</li><li><code>creational/builder/Builder.md</code> — the <code>builder()</code> entry point Lombok generates is the same trap.</li><li><code>todo/FoundationsToRead.md</code> » &quot;Static factory methods (Effective Java Item 1)&quot; — the foundations checklist entry.</li></ul>`,56)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
